cBrStr = function(l1_0)
    local l1_1 = ""
    for l1_5 = 1, string.len(l1_0), 1 do
        l1_1 = l1_1 .. string.sub(l1_0, l1_5, l1_5)
        if l1_5 % 24 == 0 then
            l1_1 = l1_1 .. "\010"
        end
    end
    return l1_1
end
