comStorySceneEnd = function(l1_0)
    advPart(false)
    if l1_0 == 0 then
        layerCopy(layerName.dlg, layerName.sys_12_a)
    elseif l1_0 == 1 then
        layerCopy(layerName.dlg, layerName.sys_12_b)
    else
        layerCopy(layerName.dlg, layerName.sys_12_c)
    end
    layerCopy(layerName.dlg + 1, layerName.sys_12_d)
    layerCopy(layerName.dlg + 2, layerName.sys_12_e)
    layerPosition(layerName.dlg + 2, 161, 87)
    layerCopy(layerName.dlg + 3, layerName.sys_12_f)
    layerPosition(layerName.dlg + 3, 180, 90)
    layerCopy(layerName.dlg + 4, layerName.sys_12_g)
    layerPosition(layerName.dlg + 4, 140, 246)
    layerClip(layerName.dlg + 4, 0, 0, 201, 18)
    switchScreen(0, "", 30)
    local l1_1 = 1
    local l1_2 = false
    local l1_3 = 1
    local l1_4 = 1
    local l1_5 = 1
    local l1_6 = 1
    while true do
        if pressButton("UP") == true then
            if l1_2 == false then
                if l1_3 == 0 then
                    l1_1 = l1_1 - 1 < 1 and 3 or l1_1 - 1
                    l1_2 = true
                end
            end
        end
        if pressButton("UP") == false then
            l1_3 = 0
        end
        if pressButton("DOWN") == true then
            if l1_2 == false then
                if l1_4 == 0 then
                    l1_1 = 3 < l1_1 + 1 and 1 or l1_1 + 1
                    l1_2 = true
                end
            end
        end
        if pressButton("DOWN") == false then
            l1_4 = 0
        end
        if pressButton("CIRCLE") == true then
            if l1_2 == false then
                if l1_5 == 0 then
                    keyPlaySE(seName.circle)
                    wait(5)
                    break
                end
            end
        end
        if pressButton("CIRCLE") == false then
            l1_5 = 0
        end
        if pressButton("CROSS") == true then
            if l1_2 == false then
                if l1_6 == 0 then
                    keyPlaySE(seName.cross)
                    wait(5)
                    l1_1 = 1
                    break
                end
            end
        end
        if pressButton("CROSS") == false then
            l1_6 = 0
        end
        if l1_2 == true then
            keyPlaySE(seName.arrowKey)
            layerMovePosition(layerName.dlg + 2, 161, 87 + (l1_1 - 1) * 25, 5)
            layerClip(layerName.dlg + 4, 0, 18 * (l1_1 - 1), 201, 18 + 18 * (l1_1 - 1))
            wait(5)
            l1_2 = false
        end
        wait(2)
    end
    layerPosition(layerName.dlg + 2, 161, 87 + (l1_1 - 1) * 25, 5)
    switchScreen(0, "", 0)
    wait(1)
    layerAlpha(layerName.dlg + 2, 0)
    switchScreen(0, "", 0)
    wait(5)
    layerAlpha(layerName.dlg + 2, 100)
    switchScreen(0, "", 0)
    wait(5)
    layerAlpha(layerName.dlg + 2, 0)
    switchScreen(0, "", 0)
    wait(5)
    layerAlpha(layerName.dlg + 2, 100)
    switchScreen(0, "", 0)
    wait(5)
    cInitGame()
    switchScreen(0, "", 30)
    wait(30)
    return l1_1
end
